module tv_recorder(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [2:0] k,\n    input [15:0] start_times [0:7],\n    input [15:0] end_times [0:7],\n    output reg [3:0] count,\n    output reg done\n);\n    \n    localparam [2:0] IDLE    = 3'd0;\n    localparam [2:0] SORT    = 3'd1;\n    localparam [2:0] INIT    = 3'd2;\n    localparam [2:0] COMPUTE = 3'd3;\n    localparam [2:0] DONE    = 3'd4;\n    \n    reg [2:0] state;\n    reg [3:0] show_idx;\n    reg [2:0] machine_idx;\n    reg [15:0] machine_end [0:3];\n    \n    reg [15:0] sorted_start [0:7];\n    reg [15:0] sorted_end [0:7];\n    reg [15:0] sort_start [0:7];\n    reg [15:0] sort_end [0:7];\n    \n    integer i, j;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            count <= 4'd0;\n            done <= 1'b0;\n            show_idx <= 4'd0;\n            machine_idx <= 3'd0;\n            for (i = 0; i < 4; i = i + 1) machine_end[i] <= 16'd0;\n            for (i = 0; i < 8; i = i + 1) begin \n                sorted_start[i] <= 16'd0;\n                sorted_end[i]   <= 16'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= SORT;\n                        for (i = 0; i < 8; i = i + 1) begin\n                            sort_start[i] <= start_times[i];\n                            sort_end[i]   <= end_times[i];\n                        end\n                    end\n                end\n                \n                SORT: begin\n                    for (i = 0; i < 7; i = i + 1) begin\n                        if (sort_end[i] > sort_end[i+1]) begin\n                            sort_end[i]   <= sort_end[i+1];\n                            sort_end[i+1] <= sort_end[i];\n                            sort_start[i] <= sort_start[i+1];\n                            sort_start[i+1] <= sort_start[i];\n                        end\n                    end\n                    for (j = 0; j < 8; j = j + 1) begin\n                        sorted_start[j] <= sort_start[j];\n                        sorted_end[j]   <= sort_end[j];\n                    end\n                    state <= INIT;\n                end\n                \n                INIT: begin\n                    for (i = 0; i < 4; i = i + 1) machine_end[i] <= 16'd0;\n                    count <= 4'd0;\n                    show_idx <= 4'd0;\n                    state <= COMPUTE;\n                end\n                \n                COMPUTE: begin\n                    if (show_idx < n && show_idx < 8) begin\n                        reg found;\n                        reg [2:0] best_machine;\n                        reg [15:0] max_end;\n                        \n                        found = 1'b0;\n                        best_machine = 3'd0;\n                        max_end = 16'd0;\n                        \n                        for (machine_idx = 0; machine_idx < k; machine_idx = machine_idx + 1) begin\n                            if (machine_end[machine_idx] <= sorted_start[show_idx]) begin\n                                if (machine_end[machine_idx] >= max_end || !found) begin\n                                    max_end = machine_end[machine_idx];\n                                    best_machine = machine_idx;\n                                    found = 1'b1;\n                                end\n                            end\n                        end\n                        \n                        if (found) begin\n                            machine_end[best_machine] <= sorted_end[show_idx];\n                            count <= count + 4'd1;\n                        end else if (show_idx < k) begin\n                            machine_end[show_idx] <= sorted_end[show_idx];\n                            count <= count + 4'd1;\n                        end\n                        \n                        show_idx <= show_idx + 4'd1;\n                    end else begin\n                        state <= DONE;\n                        done <= 1'b1;\n                    end\n                end\n                \n                DONE: begin\n                    done <= 1'b0;\n                    if (!start) state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule